package ro.leo.visual;
import ro.leo.i18n.L;
import android.app.*;import android.content.*;import android.os.Bundle;import java.util.*;
public final class NotificationSettingsActivity extends LeoActivity {
    protected void onResume(){super.onResume();show();}
    private void show(){String[] previews={L.t("Ascunse"),L.t("Doar titluri"),L.t("Titlu și text")};int mode=Math.max(0,Math.min(2,getSharedPreferences("appearance",0).getInt("lock-preview",0)));list(L.t("Notificări Leo"),Arrays.asList(L.t("Deschide centrul de notificări"),L.t("La blocare · ")+previews[mode],L.t("Sunet pentru notificări"),L.t("Acces Leo · ")+(LeoNotificationService.active==null?L.t("Neconectat"):L.t("Conectat")),L.t("Insigne Telefon / Mesaje")),0,new Choice(){public void pick(int i){if(i==0)startActivity(new Intent(NotificationSettingsActivity.this,NotificationsActivity.class));else if(i==1)options(L.t("Previzualizare la blocare"),new String[]{L.t("Ascunde"),L.t("Doar titluri"),L.t("Titlu și text vizibil")},new Choice(){public void pick(final int n){if(n==2)options(L.t("Text vizibil pe ecranul blocat"),new String[]{L.t("Anulează"),L.t("Afișează textul")},new Choice(){public void pick(int yes){if(yes==1)savePreview(n);}});else savePreview(n);}});else if(i==2)startActivity(new Intent(NotificationSettingsActivity.this,SoundSettingsActivity.class));else if(i==3){LeoNotificationService.reconnect(NotificationSettingsActivity.this);notice(L.t("Reconectare cerută; actualizează pagina"));}else notice(L.t("Număr local de SMS necitite și apeluri pierdute. Conversația și istoricul le marchează văzute; nimic nu este trimis automat."));}},L.t("Actualiz."),new Runnable(){public void run(){show();}});}
    private void savePreview(int value){getSharedPreferences("appearance",0).edit().putInt("lock-preview",value).apply();show();}
}
